cmd:
mkdir -p /app/mipsbuild/obj && cd /app/mipsbuild && cat > img_wrap.c <<'EOF'
/* Wrapper that restores the includes the user removed from doomgeneric_img.c */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "doomkeys.h"
#include "doomgeneric.h"

#include "/app/doomgeneric/doomgeneric/doomgeneric_img.c"
EOF
echo created; mipsel-linux-gnu-gcc -mabi=o32 -Os -fno-pic -fno-stack-protector -fno-asynchronous-unwind-tables -DNORMALUNIX -DLINUX -D_DEFAULT_SOURCE -I/app/doomgeneric/doomgeneric -c img_wrap.c -o obj/doomgeneric_img.o 2>&1 | head -40; ls -la obj/

cd /app/doomgeneric/doomgeneric && cat > my_stdlib.h <<'EOF'
/*
 * my_stdlib.h - minimal C library facade for the VM build.
 *
 * Provides the standard C library declarations used by doomgeneric_img.c
 * (the bare platform layer for the MIPS VM build). The actual
 * implementations live in the custom runtime (runtime.c) which issues
 * syscalls with the number set understood by vm.js (read=0, write=1,
 * open=2, close=3, lseek=8, ...).
 */
#ifndef MY_STDLIB_H
#define MY_STDLIB_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/time.h>

#endif /* MY_STDLIB_H */
EOF
echo OK && ls -la my_stdlib.h

cd /app/mipsbuild && cat > link.ld <<'EOF'
ENTRY(main)
SECTIONS
{
  . = 0x400000;
  .text : {
    KEEP(*(.text.startup))
    *(.text .text.*)
    . = ALIGN(4);
  }
  . = ALIGN(16);
  .rodata : {
    *(.rodata .rodata.*)
    *(.gnu.linkonce.r*)
    . = ALIGN(4);
  }
  . = ALIGN(16);
  .data : {
    *(.data .data.*)
    *(.gnu.linkonce.d*)
    . = ALIGN(4);
  }
  .bss : {
    . = ALIGN(16);
    *(.bss .bss.*)
    *(.gnu.linkonce.b*)
    *(COMMON)
    . = ALIGN(16);
  }
  /DISCARD/ : {
    *(.comment)
    *(.note.*)
    *(.eh_frame*)
    *(.rdata)
    *(.gnu.version*)
  }
}
EOF
echo "link.ld created" && cat > /tmp/empty.c <<'EOF'
void runtime_stub(void) {}
EOF
./build.sh 2>&1 | grep -v "^$" | head -80
